#!/usr/bin/env python3
"""Generate test/verifiers/VerifierSymbolic.t.sol (Halmos `check_*` symbolic properties; also run as
Foundry fuzz tests by the `testFuzz_` wrappers). One block per circuit; N = number of public signals."""
CIRCUITS = [("BetAuth", 10), ("SettlementCredit", 6), ("Withdrawal", 5), ("BetCancel", 5), ("CancelCredit", 6),
            ("Deposit", 3), ("PositionClose", 5), ("PartialCredit", 5), ("Consolidate", 6)]
import re

def snake(n): return re.sub(r"(?<!^)(?=[A-Z])", "_", n).lower()

out = ['''// SPDX-License-Identifier: MIT
// GENERATED by verifiers/gen_symbolic_tests.py -- do not edit by hand.
pragma solidity ^0.8.24;

import {Test} from "forge-std/Test.sol";
import {ERC1967Proxy} from "@openzeppelin/contracts/proxy/ERC1967/ERC1967Proxy.sol";
''']
for n, _ in CIRCUITS:
    out.append(f'import {{{n}G16Base, {n}Verifier}} from "polyshield/verifiers/{n}Verifier.sol";')
out.append('''
/// @notice Symbolic (Halmos) / fuzz (Foundry) properties of the on-chain Groth16 verification layer.
///
///  P1 canonicality   : for ANY proof and ANY public-signal vector in which SOME signal s_i >= r (the BN254
///                      scalar-field modulus), the base verifier AND the IVerifier adapter return false.
///                      => a public input can never be replayed in a non-canonical alias (s, s+r, s+2r, ...),
///                         which would otherwise let one proof authorise several distinct on-chain values
///                         (nullifier / amount / market_id aliasing).
///  P2 transparency   : the adapter forwards (pA, pB, pC) and the public signals to the base verifier
///                      verbatim and in order (no reordering, truncation, or re-encoding) for ALL inputs.
contract VerifierSymbolic is Test {
    uint256 internal constant R = 21888242871839275222246405745257275088548364400416034343698204186575808495617;

    function _proxy(address impl, bytes memory init) internal returns (address) {
        return address(new ERC1967Proxy(impl, init));
    }
''')
for n, N in CIRCUITS:
    s = snake(n)
    ANY = ' || '.join(f's[{k}] >= R' for k in range(N))
    out.append(f'''
    // ───────────────────────── {n} ({N} public signals) ─────────────────────────
    function _{s}Adapter() internal returns (Mock{N}Setter) {{
        return Mock{N}Setter(_proxy(address(new {n}Verifier()), abi.encodeCall({n}Verifier.initialize, (address(this)))));
    }}

    function check_{s}_base_rejects_noncanonical(
        uint256[2] memory pA, uint256[2][2] memory pB, uint256[2] memory pC, uint256[{N}] memory s
    ) public {{
        vm.assume({ANY});
        {n}G16Base b = new {n}G16Base();
        assertFalse(b.verifyProof(pA, pB, pC, s));
    }}

    function check_{s}_adapter_rejects_noncanonical(
        uint256[2] memory pA, uint256[2][2] memory pB, uint256[2] memory pC, uint256[{N}] memory s
    ) public {{
        vm.assume({ANY});
        {n}Verifier v = {n}Verifier(address(_{s}Adapter()));
        bytes32[] memory pub = new bytes32[]({N});
        for (uint256 k = 0; k < {N}; k++) pub[k] = bytes32(s[k]);
        assertFalse(v.verify(abi.encode(pA, pB, pC), pub));
    }}

    function check_{s}_adapter_forwards_verbatim(
        uint256[2] memory pA, uint256[2][2] memory pB, uint256[2] memory pC, uint256[{N}] memory s
    ) public {{
        {n}Verifier v = {n}Verifier(address(_{s}Adapter()));
        Echo{N} echo = new Echo{N}(keccak256(abi.encode(pA, pB, pC, s)));
        v.setBase(address(echo));
        bytes32[] memory pub = new bytes32[]({N});
        for (uint256 k = 0; k < {N}; k++) pub[k] = bytes32(s[k]);
        // echo returns true iff it received exactly (pA,pB,pC,s) in this order
        assertTrue(v.verify(abi.encode(pA, pB, pC), pub));
    }}

    /// Foundry fuzz twin of the two P1 checks (random proof + one forced non-canonical signal).
    function testFuzz_{s}_noncanonical(
        uint256[2] memory pA, uint256[2][2] memory pB, uint256[2] memory pC, uint256[{N}] memory s, uint256 i, uint256 x
    ) public {{
        i = bound(i, 0, {N - 1});
        s[i] = R + bound(x, 0, type(uint256).max - R);
        check_{s}_base_rejects_noncanonical(pA, pB, pC, s);
        check_{s}_adapter_rejects_noncanonical(pA, pB, pC, s);
    }}
''')
out.append("}  // contract VerifierSymbolic\n")
# per-N helper contracts
for N in sorted({N for _, N in CIRCUITS}):
    out.append(f'''
interface Mock{N}Setter {{ function setBase(address) external; }}

/// base-verifier stand-in: returns true iff the forwarded arguments hash to the expected value
contract Echo{N} {{
    bytes32 immutable expected;
    constructor(bytes32 e) {{ expected = e; }}
    function verifyProof(uint256[2] calldata a, uint256[2][2] calldata b, uint256[2] calldata c, uint256[{N}] calldata s)
        external view returns (bool)
    {{
        return keccak256(abi.encode(a, b, c, s)) == expected;
    }}
}}
''')
out_s = "\n".join(out)
open("test/verifiers/VerifierSymbolic.t.sol", "w").write(out_s)
print("generated", len(out_s), "bytes")
